Create Client.code:
// Create an individual client and activate them on the spot.
request('/clients', {
  method: 'POST',
  data: {
    officeId: 1,
    legalFormId: 1, // 1 = PERSON, 2 = ENTITY
    firstname: $.data.firstName,
    lastname: $.data.lastName,
    mobileNo: $.data.phone,
    dateOfBirth: $.data.dob,            // dd MMMM yyyy
    dateFormat: 'dd MMMM yyyy',
    locale: 'en',
    active: true,
    activationDate: $.data.activationDate,
  },
});

Record Loan Repayment.code:
// Record a repayment for a loan.
request(`/loans/${$.data.loanId}/transactions?command=repayment`, {
  method: 'POST',
  data: {
    transactionDate: $.data.transactionDate,
    transactionAmount: $.data.amount,
    paymentTypeId: $.data.paymentTypeId,
    dateFormat: 'dd MMMM yyyy',
    locale: 'en',
  },
});

Open Savings Account.code:
// Open a savings account.
request('/savingsaccounts', {
  method: 'POST',
  data: {
    clientId: $.data.clientId,
    productId: $.configuration.savingsProductId,
    submittedOnDate: $.data.today,
    dateFormat: 'dd MMMM yyyy',
    locale: 'en',
  },
});

Register Webhook Hook.code:
// Register a webhook for Loan disbursements.
request('/hooks', {
  method: 'POST',
  data: {
    name: 'Web',
    isActive: true,
    displayName: 'OpenFn — Loan Disbursed',
    events: [{ actionName: 'DISBURSE', entityName: 'LOAN' }],
    config: {
      'Content Type': 'json',
      'Payload URL': $.configuration.openfnWebhookUrl,
    },
  },
});

API Request (Beta).code:
// Make an arbitrary request against the Fineract API.
request('/clients', {
  method: 'GET',
  query: { limit: 50 },
});

Find Client by External ID.code:
// Find a client by externalId.
request('/clients', {
  method: 'GET',
  query: { externalId: $.data.nationalId },
});

Get Loan with Repayment Schedule.code:
// Fetch a loan with associations.
request(`/loans/${$.data.loanId}`, {
  method: 'GET',
  query: { associations: 'repaymentSchedule,transactions' },
});

Poll Recently Updated Loans.code:
// Poll loans submitted since the last cursor.
request('/loans', {
  method: 'GET',
  query: {
    submittedOnDateFrom: $.cursor.submittedOnDate,
    dateFormat: 'dd MMMM yyyy',
    locale: 'en',
  },
});
